Your expense tracker is below. Add an item, pick a category and an amount, and it shows totals by category and what is left of your budget. Entries may not stay once you close this chat, so note down the total before you leave.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f7f5;color:#222;max-width:560px}
  h2{margin:0 0 12px;font-size:20px}
  .card{background:#fff;border-radius:12px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select,button{font:inherit;padding:8px;border:1px solid #ccc;border-radius:8px}
  input{flex:1;min-width:90px}
  button{background:#2f7d5b;color:#fff;border:none;cursor:pointer}
  button.x{background:none;color:#b00;padding:2px 8px}
  .big{font-size:24px;font-weight:600}
  .muted{color:#666;font-size:13px}
  .bar{height:8px;background:#e5e8e3;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar div{height:100%;background:#2f7d5b}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
  .over{color:#b00}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px;align-items:center">
    <label class="muted" for="budget">Budget (₹)</label>
    <input id="budget" type="number" min="0" value="50000">
  </div>
  <div id="left" class="muted"></div>
</div>

<div class="card">
  <div class="row">
    <input id="name" type="text" placeholder="What was it?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button id="add">Add expense</button>
  </div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">By category</div>
  <div id="cats"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">All expenses</div>
  <div id="list"></div>
</div>

<script>
var items = [];
try { items = JSON.parse(localStorage.getItem('foo-exp') || '[]'); } catch (e) {}
var $ = function (id) { return document.getElementById(id); };
var fmt = function (n) { return '₹' + Number(n).toLocaleString('en-IN'); };

function save() { try { localStorage.setItem('foo-exp', JSON.stringify(items)); } catch (e) {} }

function render() {
  var total = items.reduce(function (s, i) { return s + i.amt; }, 0);
  $('total').textContent = fmt(total);

  var budget = Number($('budget').value) || 0;
  var left = budget - total;
  var l = $('left');
  l.className = 'muted' + (left < 0 ? ' over' : '');
  l.textContent = budget ? (left >= 0 ? fmt(left) + ' left of your budget' : fmt(-left) + ' over your budget') : '';

  var sums = {};
  items.forEach(function (i) { sums[i.cat] = (sums[i.cat] || 0) + i.amt; });
  var cats = $('cats');
  cats.textContent = '';
  var keys = Object.keys(sums).sort(function (a, b) { return sums[b] - sums[a]; });
  if (!keys.length) cats.textContent = 'Nothing yet.';
  keys.forEach(function (k) {
    var w = document.createElement('div');
    var t = document.createElement('div');
    t.style.display = 'flex';
    t.style.justifyContent = 'space-between';
    var a = document.createElement('span'); a.textContent = k;
    var b = document.createElement('span'); b.textContent = fmt(sums[k]);
    t.appendChild(a); t.appendChild(b);
    var bar = document.createElement('div'); bar.className = 'bar';
    var fill = document.createElement('div');
    fill.style.width = (total ? Math.round(sums[k] / total * 100) : 0) + '%';
    bar.appendChild(fill);
    w.appendChild(t); w.appendChild(bar);
    cats.appendChild(w);
  });

  var list = $('list');
  list.textContent = '';
  if (!items.length) list.textContent = 'Nothing yet.';
  items.slice().reverse().forEach(function (it) {
    var idx = items.indexOf(it);
    var r = document.createElement('div'); r.className = 'item';
    var left = document.createElement('span');
    left.textContent = it.name + ' · ' + it.cat;
    var right = document.createElement('span');
    var amt = document.createElement('span'); amt.textContent = fmt(it.amt);
    var del = document.createElement('button'); del.className = 'x'; del.textContent = '✕';
    del.onclick = function () { items.splice(idx, 1); save(); render(); };
    right.appendChild(amt); right.appendChild(del);
    r.appendChild(left); r.appendChild(right);
    list.appendChild(r);
  });
}

$('add').onclick = function () {
  var amt = Number($('amt').value);
  if (!amt || amt <= 0) return;
  items.push({ name: $('name').value.trim() || 'Expense', cat: $('cat').value, amt: amt });
  $('name').value = '';
  $('amt').value = '';
  save();
  render();
};
$('budget').oninput = render;
render();
</script>
</body>
</html>
```
